def run(context):
    # Analyze VCP picks and return synthesized analysis
    vcp_candidates = context['stage2_vcp_picks'].sort_values(by='vcp_score', ascending=False)
    top_sectors = vcp_candidates['sector'].value_counts().head(3).index.tolist()
    risk_assessment = vcp_candidates[['symbol', 'investment_score']].head(5)
    return {'vcp_candidates': list(vcp_candidates['symbol'].head(5)), 'sector_leadership': top_sectors, 'risk_assessment': risk_assessment.to_dict()}

